<?php
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/session.php';require_once __DIR__.'/../includes/functions.php';if(!is_attendee_logged_in())redirect('../index.php');
if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf_token($_POST['csrf_token']??'')){$_SESSION['attendance_error']='Security token expired.';redirect('dashboard.php');}
$id=(int)($_POST['registration_id']??0);$action=$_POST['action']??'';$r=pg_query_params($conn,"SELECT r.id,e.id event_id,e.title,e.status,e.allow_self_checkin,ar.id attendance_id,ar.check_out_at FROM event_registrations r JOIN events e ON e.id=r.event_id JOIN attendees a ON a.id=r.attendee_id LEFT JOIN attendance_records ar ON ar.registration_id=r.id WHERE r.id=$1 AND r.attendee_id=$2 AND r.status='registered' AND a.must_complete_profile=FALSE",[$id,$_SESSION['attendee_id']]);
if(!$r||!pg_num_rows($r)){$_SESSION['attendance_error']='Registration not found.';redirect('dashboard.php');}$row=pg_fetch_assoc($r);
if($action==='checkin'){if($row['status']!=='ongoing'||!($row['allow_self_checkin']==='t'||$row['allow_self_checkin']===true))$_SESSION['attendance_error']='Self check-in is not open for this event.';elseif($row['attendance_id'])$_SESSION['attendance_error']='Attendance is already recorded.';else{$ok=pg_query_params($conn,"INSERT INTO attendance_records(registration_id,check_in_method) VALUES($1,'self') ON CONFLICT DO NOTHING",[$id]);$_SESSION['attendance_message']=pg_affected_rows($ok)?'You are checked in to '.$row['title'].'.':'Attendance is already recorded.';}}
elseif($action==='checkout'){if(!$row['attendance_id']||$row['check_out_at'])$_SESSION['attendance_error']='No open check-in was found.';else{pg_query_params($conn,"UPDATE attendance_records SET check_out_at=NOW(),check_out_method='self',updated_at=NOW() WHERE registration_id=$1 AND check_out_at IS NULL",[$id]);$_SESSION['attendance_message']='You have checked out of '.$row['title'].'.';}}
redirect('dashboard.php');
